// Support's ready-made questions and How-to guides (SPEC.md section 14), kept here so they change with the app. Each says who
// it's for and which features it needs; lib/support.ts shows a person only theirs. How-to: one step a line.
// When a feature changes, change its articles here (lib/support-library.test.ts checks every feature is covered).

// public: the organization's public page (no login). start: an account in no organization yet. parent: a family login.
// staff: Team Managers and Team Parents. director: limited to their areas. admin and owner see the directors' too.
export const AUDIENCES = ["everyone", "public", "start", "parent", "staff", "coach", "director", "admin", "owner", "official"] as const;
export type Audience = (typeof AUDIENCES)[number];
export const AUDIENCE_LABEL: Record<Audience, string> = {
  everyone: "Everyone",
  public: "Public page",
  start: "New accounts",
  parent: "Parents",
  staff: "Team Managers & Team Parents",
  coach: "Coaches",
  director: "Directors",
  admin: "Admins",
  owner: "Owners",
  official: "Officials",
};

// What an article can need: the organization's features (lib/features.ts), as abilities or keys, CourtSync's part, and
// "has-teams" (it has at least one, or runs a League) and "typed-rosters" (its teams, without CourtPlayers: rosters typed in by the team).
export const NEEDS = {
  "court-players": "CourtPlayers",
  "court-teams": "CourtEvents",
  "court-club": "CourtClub",
  "court-facilities": "CourtFacilities",
  "court-playbook": "CourtPlaybook",
  "court-officials": "CourtOfficials",
  "court-sync": "CourtSync",
  alerts: "Alerts",
  practice: "CourtPractice",
  uniforms: "Uniforms",
  chat: "Chat",
  "team-chat": "Team chats",
  "team-building": "Its own teams",
  "has-teams": "Has teams",
  "typed-rosters": "Typed-in rosters (no CourtPlayers)",
  "sync-host": "CourtSync Host",
  "sync-scheduler": "CourtSync Scheduler",
  "sync-officials": "CourtSync Officials",
} as const;
export type Need = keyof typeof NEEDS;

export const TOPICS = [
  "Logging in",
  "Finding your way",
  "Your players",
  "Your team",
  "Rosters",
  "Games & schedules",
  "Practices",
  "Uniforms",
  "Playbook",
  "Registering & paying",
  "Teams",
  "Players & tryouts",
  "Members & roles",
  "Programs & leagues",
  "Scheduling",
  "Scores & standings",
  "Gyms & hosting",
  "Officials",
  "Chat & alerts",
  "Settings & payments",
  "Public page & sharing",
] as const;
export type Topic = (typeof TOPICS)[number];

export type LibraryArticle = {
  key: string;
  kind: "faq" | "howto";
  topic: Topic;
  title: string;
  body: string;
  who: readonly Audience[];
  needs?: readonly Need[]; // all of them
  areas?: readonly string[]; // a Director with one of these areas (Admins and Owners see it anyway)
};

const managers = ["director", "admin", "owner"] as const;
const admins = ["admin", "owner"] as const;
const team = ["coach", "staff"] as const;

export const LIBRARY: readonly LibraryArticle[] = [
  // ---- Logging in
  { key: "log-in", kind: "faq", topic: "Logging in", who: ["everyone", "public", "start"], title: "How do I log in?", body: "Use your organization's login link: enter your cell number, then your 4-digit PIN. If someone set you up, your starter PIN is 1234: the first time you confirm your email with a code and choose your own PIN." },
  { key: "forgot-pin", kind: "faq", topic: "Logging in", who: ["everyone", "public", "start"], title: "I forgot my PIN.", body: "Enter your cell, then tap Forgot PIN? A code goes to your confirmed email; enter it and choose a new PIN. If it says to contact the Director, ask your organization's Admin to reset your login: your PIN goes back to 1234." },
  { key: "locked-out", kind: "faq", topic: "Logging in", who: ["everyone", "public", "start"], title: "It says too many tries.", body: "After 5 wrong PINs that cell is locked for 15 minutes. Wait, or use Forgot PIN? to choose a new one." },
  { key: "no-code", kind: "faq", topic: "Logging in", who: ["everyone", "public", "start"], title: "I didn't get the email code.", body: "Check junk mail, and that the email shown (with stars) is yours. Codes last 15 minutes and you can get 3 an hour. Wrong or old email? Ask your organization's Admin to reset your login, then log in and enter the right one." },
  { key: "not-set-up", kind: "faq", topic: "Logging in", who: ["public"], title: "It says I'm not set up yet.", body: "Coaches are set up by their organization first. Ask your Director to add you with the cell you're using, then log in with starter PIN 1234." },
  { key: "stay-logged-in", kind: "faq", topic: "Logging in", who: ["everyone"], title: "Why was I logged out?", body: "You stay logged in on a phone or computer for 72 hours, or until you tap Log out. Then your PIN is asked again." },

  // ---- Finding your way
  { key: "header-icons", kind: "faq", topic: "Finding your way", who: ["everyone"], title: "What are the icons at the top?", body: "Your name opens My dashboard. 💬 is Chat, the bell is your alerts, and ? Support is help (also a card at the end of your team page or dashboard). Admins also have the gear (Organization settings); Owners, Admins and Directors have 🔍 search. The logo by Log out switches organizations." },
  { key: "switch-org", kind: "faq", topic: "Finding your way", who: ["everyone"], title: "How do I switch organizations or roles?", body: "Organizations: tap the logo by Log out and pick one. Roles or teams in the same organization: tap the chips under the name. The one you used last is remembered." },
  { key: "missing-button", kind: "faq", topic: "Finding your way", who: [...managers, "coach", "staff"], title: "Why don't I see a card or a button?", body: "What you see follows your role (Owner, Admin, Director of an area, coach, team staff) and the features your organization has. Ask your organization's Admin for the area you need. Admins: features are in the gear, under Features & Upgrades." },
  { key: "my-dashboard", kind: "faq", topic: "Finding your way", who: ["everyone"], title: "What is My dashboard?", body: "Tap your name. It shows your cell and email, your roles in every organization, your players and any fees still owed, your teams, and games you're on as an official." },
  { key: "red-cards", kind: "faq", topic: "Finding your way", who: [...managers, "coach"], title: "Why is a card flashing red?", body: "Something inside needs to be entered or answered, like a Head Coach, a roster, a birthdate or a score. Open the red card, then the red line inside it, until you reach what's missing. It stops when it's fixed." },
  { key: "search-org", kind: "howto", topic: "Finding your way", who: managers, title: "Find a person, player or team", body: "Tap 🔍 at the top.\nType part of a name, a cell or a parent's name; each word can be any part.\nTap a result to see the cell, email, teams and links." },
  { key: "who-sees-me", kind: "faq", topic: "Finding your way", who: ["everyone"], title: "Who can see my information?", body: "Your organization's Owners, Admins and the Directors whose area you're in, your team's staff, and CourtCaptain staff when helping. Other organizations can't. Public pages show team names, games and scores; a followed team's roster shows first names and last initials only." },
  { key: "start-choices", kind: "faq", topic: "Finding your way", who: ["start"], title: "I have an account but no organization. What now?", body: "Coaching for an organization already here? Ask its Director to add your cell, then use its login link. Have teams of your own? Start an organization: you'll be its Owner, and can add teams and register them for programs." },
  { key: "start-org", kind: "howto", topic: "Finding your way", who: ["start"], title: "Start an organization", body: "From your home, tap Start an organization.\nEnter its name, short name, type and color, and a logo if you have one.\nYou're its Owner: open Teams and tap + to add your teams." },

  // ---- Parents
  { key: "parent-find-team", kind: "howto", topic: "Your players", who: ["public", "parent"], needs: ["court-players"], title: "Find my player's team", body: "On the organization's public page, open Find my player's team under Parents.\nEnter the cell that's on the registration; a code goes to the email on it.\nEnter the code: you'll see each player's team, its staff with their cells, and coming practices and games.\nIt's shown once; get a new code to look again." },
  { key: "parent-not-on-team", kind: "faq", topic: "Your players", who: ["public", "parent"], needs: ["court-players"], title: "It says my player isn't on a team yet.", body: "The organization's Directors place players on teams. If teams are out and yours still isn't on one, contact the organization." },
  { key: "parent-wrong-info", kind: "faq", topic: "Your players", who: ["public", "parent"], needs: ["court-players"], title: "My cell or email on the registration is wrong.", body: "Tell your player's coach or the organization. The team's staff can add a missing parent; a Director of Players can fix what's there. Then use the new cell." },
  { key: "parent-login", kind: "faq", topic: "Your players", who: ["public", "parent"], needs: ["court-players"], title: "Can parents have a login?", body: "Yes. Log in with the cell on your player's registration and confirm your email. My dashboard then shows your players, any fees still owed and each team: what's coming (✓ or ✗), the schedule, the staff, the roster and the Parents chat." },
  { key: "parent-fees", kind: "faq", topic: "Your players", who: ["parent"], needs: ["court-players"], title: "What do I still owe?", body: "Tap your name: My dashboard shows each player's fees still owed, from the registration. Pay where you registered. Something wrong? Start a chat below." },
  { key: "parent-uniform", kind: "faq", topic: "Your players", who: ["parent"], needs: ["uniforms"], title: "How do uniform sizes and numbers work?", body: "The size and number you asked for at registration are hints. Your player's coach sets the real number and size. Need a uniform, or a different size? Tell the coach." },
  { key: "parent-chat", kind: "faq", topic: "Your players", who: ["parent"], needs: ["team-chat"], title: "Where is the parents chat?", body: "Tap 💬 at the top. Your player's team has a Parents chat with its staff and the other parents who have logins." },
  { key: "follow-team", kind: "howto", topic: "Games & schedules", who: ["public", "parent"], title: "Follow a team", body: "Open the organization's public page.\nTap ☆ by the team (under Teams, or in a League's Standings).\nIt moves to My teams on that phone: next games, latest final, roster and schedule.\nNo login needed; a private window or cleared data forgets it." },
  { key: "public-schedule", kind: "faq", topic: "Games & schedules", who: ["public", "parent"], title: "Where are the schedule, gyms and standings?", body: "Open the League on the public page. Pick the division, REC or COMP, then the grade: Standings, then the Schedule with gym, court and Directions. The League's Gyms card lists every gym." },
  { key: "schedule-soon", kind: "faq", topic: "Games & schedules", who: ["public", "parent", "coach", "staff"], title: "Why does it say the schedule will be published soon?", body: "REC and COMP are published separately for each Game Day by the League. Games show as soon as that level is published for that day." },
  { key: "tba", kind: "faq", topic: "Games & schedules", who: ["public", "parent", "coach", "staff"], title: "What do TBA and TBD mean?", body: "TBA: the game's time and court aren't set yet. TBD: its opponent isn't set yet." },
  { key: "share-final", kind: "howto", topic: "Public page & sharing", who: ["public", "parent", "coach", "staff"], title: "Share a final score", body: "Find the game on the public page (My teams, Teams or the Schedule).\nTap the share icon by the Final: it appears 10 minutes after the score is entered.\nTap Share picture and choose Instagram, Facebook, X or Messages, or Save picture." },
  { key: "games-of-week", kind: "faq", topic: "Scores & standings", who: ["public", "parent", "coach"], title: "How are Games of the Week and standings worked out?", body: "Games of the Week: the coming Game Day's best matchups by both teams' records (tap ⓘ for the rules). Standings are by Power Index (PI, 0 to 1000): everyone starts at 500, and wins against stronger teams count more." },

  // ---- Your team (coaches and team staff)
  { key: "team-page", kind: "faq", topic: "Your team", who: team, title: "What's on my team page?", body: "Next 10 days at the top, then cards: registrations, Staff, Roster, Games, and, when your organization has them, Uniforms, Practices and Playbook. Tap a card to open it; its icons work while it's closed." },
  { key: "who-does-what", kind: "faq", topic: "Your team", who: [...team, ...managers], needs: ["has-teams"], title: "What can each team role do?", body: "Head Coach: everything on the team, including adding its other staff. Assistant Coach: the same, except adding Assistant Coaches. Team Manager: attendance, rosters that are typed in, uniforms and booking practices. Team Parent: sees the team and helps with rosters and attendance, but can't book practices." },
  { key: "add-team-staff", kind: "howto", topic: "Your team", who: ["coach"], title: "Add an Assistant Coach, Manager or Team Parent", body: "Open your team page and tap the person-plus on the Staff card.\nPick the role. A Head Coach adds any of them; an Assistant Coach adds Managers and Team Parents.\nPick someone listed, or enter their name and cell. They log in with that cell and starter PIN 1234.\nA green ✓ shows once their email is confirmed." },
  { key: "contact-team", kind: "howto", topic: "Your team", who: team, title: "Text or email my team's staff and parents", body: "Open your team page.\nStaff card: 💬 texts and ✉️ emails the staff.\nRoster card: 💬 texts and ✉️ emails the parents, when your organization has their contacts.\nA group text opens in your phone's Messages; emails put everyone in Bcc." },
  { key: "attendance", kind: "howto", topic: "Your team", who: team, title: "Take attendance", body: "On your team page, open a game or practice in Next 10 days.\nTap ✓ here or ✗ absent by each player; tap again to clear.\nIt opens 15 minutes before the start and closes 24 hours after." },
  { key: "coach-info-red", kind: "faq", topic: "Your team", who: [...managers, "coach"], needs: ["has-teams"], title: "What does COACH INFO MUST BE ENTERED mean?", body: "The team has no Head Coach, or the coach's cell or email is missing. A Director of Teams or an Admin adds the Head Coach on the team's Staff card; the team is then named after them. A coach's email is confirmed the first time they log in." },

  // ---- Rosters
  { key: "roster-players", kind: "faq", topic: "Rosters", who: team, needs: ["court-players"], title: "How do players get on my team?", body: "Your organization's Directors place registered players on teams. You can see the roster, parents and eligibility, but not change who's on it. Mark players you'd like as Interested." },
  { key: "evaluate", kind: "howto", topic: "Rosters", who: ["coach"], needs: ["court-players"], title: "Evaluate players", body: "Open your team's Roster card, then Available players (or Evaluate).\nSet position, height, speed, a 1 to 5 score and notes; each tap saves.\nTap Interested on players you'd like. Only your team and the Directors see your ratings." },
  { key: "add-parent", kind: "howto", topic: "Rosters", who: team, needs: ["court-players"], title: "Add a player's missing parent", body: "On your team's Roster, tap the player.\nTap + Add parent and enter their name, cell and email.\nThey can log in with that cell after confirming the email. You can fix what you added, not what the family gave." },
  { key: "parent-view", kind: "howto", topic: "Rosters", who: ["coach", ...managers], needs: ["court-players"], areas: ["teams", "players"], title: "See what a parent sees", body: "Open the team's Roster card and tap a player.\nTap 👁 by a parent. It opens right there, view only, even if they've never logged in.\nCoaches see that parent's players on their own team. Directors of Teams or Players and Admins see the whole family; fees show to Directors of Players and Admins.\nChats and alerts are never shown." },
  { key: "type-roster", kind: "howto", topic: "Rosters", who: [...team, ...managers], needs: ["has-teams", "typed-rosters"], areas: ["teams"], title: "Enter a team's roster", body: "Open the team page, then the Roster card.\nTap Add player: first, last, grade, uniform number and birthdate. Or Import players to paste many at once.\nTap a player to fix their name, grade, number or birthdate.\nAll of the team's staff can add and fix; coaches and Directors remove." },
  { key: "league-roster-type", kind: "howto", topic: "Rosters", who: ["coach"], needs: ["court-teams"], title: "Enter my League team's roster", body: "Open your team page, then the Roster card.\nTap Add player or Import players: name, grade, uniform number and birthdate.\nFinish before your first game: that's when your League roster locks." },
  { key: "roster-red", kind: "faq", topic: "Rosters", who: [...team, ...managers], needs: ["has-teams"], areas: ["teams"], title: "What do the red roster warnings mean?", body: "ROSTER MUST BE ENTERED: no players yet. PLAYER BIRTHDATES MUST BE ENTERED: someone has none. CHECK PLAYER BIRTHDATES: one can't be right for the grade. Too old or Grade too high: the player isn't eligible for that team." },
  { key: "roster-lock", kind: "faq", topic: "Rosters", who: [...team, ...managers], needs: ["has-teams"], areas: ["teams", "programs"], title: "When does a roster lock?", body: "A team's League roster is saved at its first game. Changing the team's roster after that doesn't change its League roster; ask the League. Uniform numbers are needed by then." },
  { key: "two-teams", kind: "faq", topic: "Rosters", who: [...team, ...managers], needs: ["has-teams"], areas: ["teams", "programs", "players"], title: "Can a player be on two teams?", body: "In a League, only on two teams of the same organization in different divisions, and never on both a REC and a COMP team. The app warns while adding a player who's already on another League team." },
  { key: "eligibility", kind: "faq", topic: "Rosters", who: [...team, ...managers], needs: ["has-teams"], areas: ["teams", "players", "programs"], title: "How is age eligibility decided?", body: "By the team's top grade and an age control date. Usual rule: a 3rd grade team's player can't turn 11 before August 1 after the school year, and each grade follows by one year. A player young enough (3rd: not 10 by then) may play in any grade. A League or organization can set its own rule." },

  // ---- Games
  { key: "where-games", kind: "faq", topic: "Games & schedules", who: team, title: "Where are my team's games?", body: "On your team page: Next 10 days, and the Games card for all of them, with gym, court and Directions. They show once the League publishes your level for that Game Day." },
  { key: "schedule-requests", kind: "howto", topic: "Games & schedules", who: ["coach", ...managers], needs: ["has-teams"], areas: ["teams"], title: "Ask for times my team can't play, or sit out a day", body: "Open the team page and its Schedule requests.\nFor each date, check the times the team can't play, up to the limit shown.\nCheck Sit out if the team won't play that day.\nDo it before the close date shown. Time requests aren't taken for the Brackets." },
  { key: "remove-from-schedule", kind: "howto", topic: "Games & schedules", who: ["coach", ...managers], needs: ["has-teams"], areas: ["teams"], title: "Take a scheduled team out of a League", body: "A team already on the schedule can't just be deleted or withdrawn.\nOn its page, tap the button that requests removal from the schedule.\nThe League's Scheduler puts TBD in its games and withdraws it. Refunds are decided by the League." },
  { key: "one-gg", kind: "faq", topic: "Games & schedules", who: [...team, ...managers], needs: ["has-teams"], areas: ["teams", "programs", "scheduling"], title: "What are 1GG, 2GG and ALL Season?", body: "Games guaranteed that day: 1GG is one, 2GG is two. ALL Season plays one game every Game Day, plus the Brackets; adding a 2nd Game makes a day 2GG. Single Day registers only the dates you pick." },

  // ---- Practices
  { key: "book-practice", kind: "howto", topic: "Practices", who: team, needs: ["practice"], title: "Book a practice", body: "On your team page, open Practices and tap the calendar (Book practices).\nPick one of your team's gyms, then an open time and court.\nCheck Every week at this time to repeat it, then Book.\nTeam Parents can see practices but not book." },
  { key: "practice-limit", kind: "faq", topic: "Practices", who: [...team, ...managers], needs: ["practice"], areas: ["practices"], title: "Why does it say limit reached?", body: "Each week a team can book one practice any time, and a second only if it starts within 72 hours. Never more than two still to come in the week. Cancel one, or wait until one is done." },
  { key: "cancel-practice", kind: "howto", topic: "Practices", who: team, needs: ["practice"], title: "Cancel a practice", body: "Open Practices on your team page.\nTap Cancel on the practice.\nPick Cancel this one or This and later weeks. The court opens for other teams at once." },
  { key: "own-gym", kind: "howto", topic: "Practices", who: team, needs: ["practice"], title: "Add a practice at our own place", body: "Open Practices, then Book practices, then 📍 Own gym.\nEnter the place, date, start time and length; Make it weekly until a date if you like.\nNo limits apply. Remove it any time before it's over." },
  { key: "practice-setup", kind: "howto", topic: "Practices", who: managers, needs: ["practice"], areas: ["practices", "facilities"], title: "Set up practice times", body: "Facilities → Gyms: tap + to add each gym and its courts (goals).\nAvailability: choose the dates and hours each gym is open for Practice Slots.\nTeam Practice Facilities: choose which gyms each team may use.\nBlackout Dates: block dates or times, this year or every year. Booked practices in a blackout are removed and listed." },
  { key: "practice-manage", kind: "faq", topic: "Practices", who: managers, needs: ["practice"], areas: ["practices"], title: "How do I see or change everyone's practices?", body: "Home → Practice has the week grid: book, release, block or unblock any court. Directors of Practices aren't held to the team limits. Practice Court Availability shows the whole season; tap a day for its week." },

  // ---- Uniforms
  { key: "set-uniforms", kind: "howto", topic: "Uniforms", who: team, needs: ["uniforms"], title: "Set uniform numbers and sizes", body: "On your team page, open Uniforms.\nGive every player a number, and a size to each who ordered; each change saves.\nUse fills in what the parent asked for.\nTick Needs a uniform for a player who didn't order one. The card is red until everything's set." },
  { key: "order-uniforms", kind: "howto", topic: "Uniforms", who: managers, needs: ["uniforms"], areas: ["uniforms"], title: "Order uniforms from the vendor", body: "Home → Uniforms lists who needs one, by team, with totals by size.\nThe gear sets the vendor's email and who gets a copy.\nFix what's held back (a missing number or size, or a duplicate number), then send the order.\n🔍 searches current and past orders." },

  { key: "order-spares", kind: "howto", topic: "Uniforms", who: managers, needs: ["uniforms"], areas: ["uniforms"], title: "Order spare uniforms, jerseys, shooting shirts or shorts", body: "Home → Uniforms, then Order Spares.\nPick one or more: Uniform sets, Jerseys, Shooting shirts, Shorts.\nSay how many, then give each a number and size. Shorts: how many of each size.\nTap Add to the next order: they wait there (✕ takes one off) and go when you Email the vendor, with the new players." },
  { key: "uniform-moves", kind: "faq", topic: "Uniforms", who: ["coach", "staff", ...managers], needs: ["uniforms"], areas: ["uniforms", "teams", "players"], title: "A player changed teams. Is their uniform ordered again?", body: "No. Their number, size and order move with them; Uniforms shows the order and the team it was for. If they really need a new one, tick Needs a uniform on the team's Uniforms." },

  // ---- Playbook
  { key: "add-play", kind: "howto", topic: "Playbook", who: ["coach", ...managers], needs: ["court-playbook"], areas: ["teams"], title: "Add a play", body: "On the team page, open Playbook and tap +.\nName it, pick Offense, Defense, Inbounds or Drill, and draw it on the court, frame by frame.\nAdd notes and up to 5 video links.\nPick who sees it: Private, Team, your organization, or Public." },
  { key: "copy-play", kind: "faq", topic: "Playbook", who: ["coach", ...admins], needs: ["court-playbook"], title: "Can I use other teams' plays?", body: "Yes. Copy plays shared with your organization, or Public plays from any organization with CourtPlaybook, into your team's playbook. Changing your copy doesn't change theirs. Owners and Admins also keep the organization's own playbook, on Home." },

  // ---- Registering & paying
  { key: "register-public", kind: "howto", topic: "Registering & paying", who: ["public", "start"], needs: ["court-teams"], title: "Register new teams for an event", body: "Registering is for NEW teams. If your team is in an organization already playing, find it by its coach's last name and contact that organization.\nOn the public page, tap Register new team by the event, then My team is new.\nEnter your cell (and PIN, if you have a login).\nEnter your organization, then each team with its Head Coach and what it's registering for.\nConfirm the code emailed to you, then pay by card if there's a fee. You're the organization's Owner." },
  { key: "find-team", kind: "howto", topic: "Games & schedules", who: ["public", "parent", "start"], needs: ["court-teams"], title: "Find a team in the League", body: "On the League's page, open Register new teams.\nType the coach's last name: teams show as you type.\nTap a team for its public view: games, roster and schedule; ☆ follows it." },
  { key: "register-all", kind: "howto", topic: "Registering & paying", who: managers, needs: ["has-teams", "team-building"], areas: ["teams"], title: "Register all our teams in a League", body: "Home → Teams → Register ALL Teams (shown while an event is open and teams aren't in it).\nCheck the teams and what each registers for.\nPay now, Pay later if your organization may, or add them to the cart.\nAll the checked teams register together." },
  { key: "register-one", kind: "howto", topic: "Registering & paying", who: managers, needs: ["has-teams", "team-building"], areas: ["teams"], title: "Register one team, or add dates", body: "Open the team page and its Register card.\nPick ALL Season or the Game Days it will play, and any 2nd Game.\nPay now, Add to cart, or Pay later when offered.\nLater, Add dates adds more while registration is open." },
  { key: "coach-add-dates", kind: "faq", topic: "Registering & paying", who: ["coach"], title: "Can a coach register the team or add dates?", body: "Your organization's Admins and Directors of Teams register its teams. Once a COMP team is registered, its Head or Assistant Coach can Add dates or a 2nd Game on the team page (not in organizations with CourtPlayers). REC dates are the Directors'." },
  { key: "scheduler-view", kind: "howto", topic: "Scheduling", who: managers, needs: ["court-teams"], areas: ["scheduling"], title: "Schedule on the whole screen", body: "Tap Scheduler View by your name.\nPick the League and the Game Day at the top; the numbers and Publish are there.\nEach gym lists the home games it should host (a host with two gyms: the one whose courts take the division and has the most room).\nTap or drag a game. Green slots fit at the home team's gym; amber ones fit at another host's gym; yellow means a team or coach has only one game's break from a game at another gym; red ones can't (back to back at another gym, a schedule request, or already playing), and say why.\n« Hide the lists gives the courts the whole screen." },
  { key: "fill-tbd", kind: "howto", topic: "Scheduling", who: managers, needs: ["court-teams"], areas: ["scheduling"], title: "Fill in a TBD, clear matchups or empty a gym", body: "A TBD: in its slot pick any team playing that day, of any level, grade or division, to play an extra game (teams that already filled in are last). Or drag TBD into the New game box and pick both teams. It keeps its place on the grid if that team is free then; Back to TBD undoes it.\nClear REC matchups or Clear COMP matchups, in a division, clears that level's matchups for the day not on the grid.\nUnschedule all, on a gym, takes its games off the grid; the matchups stay.\nPublished games stay as they are." },
  { key: "who-is-home", kind: "faq", topic: "Scheduling", who: managers, needs: ["court-teams"], areas: ["scheduling"], title: "How is the home team chosen?", body: "The team whose organization hosts (has a gym open that day) is home against one that doesn't. In each division, about half of each hosting organization's teams' games are at home, even when its gym only takes some divisions; then hosts' home games are kept as even as possible over the whole day, within their open court times; then teams alternate home and away. REC is planned first, youngest to oldest, then COMP. Coaches with several teams are kept all home or all away where possible. To change it, drag one team onto the other in the same game: home and away switch." },
  { key: "registered-grade", kind: "faq", topic: "Teams", who: ["coach", ...managers], needs: ["has-teams"], areas: ["teams"], title: "Can we change our team's grade or level after registering?", body: "Yes: change anything about your team. Its division in the League stays where it registered, though. If it needs to play in another division or grade, ask the League: it can place your team there." },
  { key: "play-in", kind: "howto", topic: "Teams", who: managers, needs: ["court-teams"], areas: ["teams"], title: "Place a team in another division", body: "Teams → open the team (↗) → Play in another division.\nPick the division and grade it plays in, and say why (its organization sees it).\nIts own gender and grade stay. If it has games, they're shown first; they become Games to correct.\nPick its own division to put it back." },
  { key: "coed-division", kind: "howto", topic: "Programs & leagues", who: managers, needs: ["court-teams"], areas: ["programs"], title: "Make a division Coed", body: "Open the League under Programs.\nAt the bottom of the division, set Division for to Coed (Boys and Girls).\nIts teams stay. Boys and Girls teams of those grades can register into it when their own gender has no division for them." },
  { key: "games-to-correct", kind: "faq", topic: "Scheduling", who: managers, needs: ["court-teams"], areas: ["scheduling"], title: "What are Games to correct?", body: "A team's grade, level or gender changed after its games were made, so a game has teams from different divisions, or REC against COMP. They flash on Home → To Do and the Scheduler, and are red on the matchups and the grid. Put TBD in the team's place, or remove the game. A published game: unpublish that level for the day first." },
  { key: "need-scheduler", kind: "howto", topic: "Scheduling", who: admins, needs: ["court-teams"], title: "Name our Director of Scheduling", body: "Every organization that runs events needs at least one; Home → To Do warns until you do.\nPick a person there, or Members → Staff, tap + and choose Director of Scheduling.\nThe list is yourself and your staff; pick New person for anyone else.\nAn Owner or Admin can be one: their gear, Make Director of Scheduling." },
  { key: "dup-numbers", kind: "faq", topic: "Rosters", who: [...team, ...managers], needs: ["has-teams"], areas: ["teams", "uniforms", "programs"], title: "What does DUPLICATE NUMBERS mean?", body: "Two players on the team have the same uniform number; it's red on the Roster. Change one on the team's Uniforms (or its Roster, where rosters are typed in). Until then neither can go in a uniform order. If it was already ordered, a coach or Director of Uniforms unlocks it first; a changed number goes in the next order." },
  { key: "need-scorer", kind: "howto", topic: "Scores & standings", who: admins, needs: ["sync-host"], title: "Name our Director of Scores", body: "Every organization that hosts games needs at least one; Home → To Do warns until you do.\nPick a person there, or Members → Staff, tap + and choose Director of Scores.\nThe list is yourself and your staff; pick New person for anyone else.\nAn Owner or Admin can be one: their gear, Make Director of Scores." },
  { key: "cart", kind: "faq", topic: "Registering & paying", who: ["coach", ...managers], needs: ["has-teams"], areas: ["teams"], title: "How does the cart work?", body: "Add to cart on each team, then pay for them together by card, or Request an invoice. It's yours alone. Nothing is registered until it's paid or an invoice is requested where allowed; prices are checked again when you pay." },
  { key: "invoices", kind: "faq", topic: "Registering & paying", who: managers, needs: ["has-teams", "team-building"], areas: ["teams"], title: "Where are our invoices?", body: "Home → Invoices shows each balance due, with View and Pay. One invoice covers all your teams in a League program; print it or save it as PDF. It's emailed to your Owners when teams register without paying and again when it's paid." },
  { key: "pay-later", kind: "faq", topic: "Registering & paying", who: managers, needs: ["has-teams", "team-building"], areas: ["teams"], title: "Can we pay later or by check?", body: "Only organizations the League has allowed see Pay later: teams register now and the invoice has its due date. For a check or cash, pay the League; its Owners mark the teams Paid." },
  { key: "refunds", kind: "faq", topic: "Registering & paying", who: ["coach", ...managers], needs: ["has-teams"], areas: ["teams"], title: "Do I get a refund if we withdraw?", body: "Not automatically. The League's Owners decide and send refunds to the card that paid; it takes 5 to 10 days to show. Contact the League." },
  { key: "rec-limited", kind: "faq", topic: "Registering & paying", who: ["public", "start", "coach", ...managers], areas: ["teams"], title: "Why can't we register REC teams?", body: "A League can limit REC to organizations it invites. COMP is open to all. Ask the League to add your organization." },

  // ---- Teams (managers)
  { key: "add-team", kind: "howto", topic: "Teams", who: managers, needs: ["team-building"], areas: ["teams"], title: "Add a team", body: "Home → Teams, tap +, then Add a team.\nPick the gender, grade (one, or two next to each other) and REC or COMP.\nPick the Head Coach: someone listed, a new person (name and cell), or none yet.\nCheck the name shown, then add it." },
  { key: "import-teams", kind: "howto", topic: "Teams", who: managers, needs: ["team-building"], areas: ["teams"], title: "Import teams from a spreadsheet", body: "Home → Teams, tap +, then Import teams.\nPaste your rows or choose a CSV file; columns can be in any order.\nCheck which column is which, then check each row: it shows what it cleaned up.\nAdd them. Recent imports has Undo." },
  { key: "team-names", kind: "faq", topic: "Teams", who: [...managers, "coach"], needs: ["has-teams"], areas: ["teams"], title: "How are team names made?", body: "Top grade + gender + a name + the Head Coach's last name, like 8B Bolts Epps. The middle name is the Alternate name, or the organization's. No coach yet: TBD. Two that would match are numbered. Change many at once with Teams → + → Edit team names." },
  { key: "eval-teams", kind: "howto", topic: "Teams", who: managers, needs: ["court-players"], areas: ["teams"], title: "Put players on teams", body: "Home → Teams, open the grade and tap Roster players.\nDrag a player onto a team, or tap the player and then the team.\nPlayers not on a team show with their coach request and who's Interested.\nA player can be on a 2nd team only if you confirm it; never a 3rd." },
  { key: "delete-team", kind: "faq", topic: "Teams", who: managers, needs: ["has-teams", "team-building"], areas: ["teams"], title: "Why can't I delete a team?", body: "A team on a League's schedule must come off it first: request removal on its page. Otherwise Delete team is at the bottom of the team page: type the team's name to confirm. It can't be undone." },
  { key: "email-coaches", kind: "howto", topic: "Teams", who: managers, needs: ["has-teams", "team-building"], areas: ["teams"], title: "Text or email all our coaches", body: "Home → Teams and tap 📣 (Members → Coaches has it too).\nText coaches opens one group text; pick who to include.\nEmail opens your email with them in Bcc, or Open in Gmail, or Copy emails." },

  // ---- Players & tryouts (CourtPlayers managers)
  { key: "player-program", kind: "howto", topic: "Players & tryouts", who: managers, needs: ["court-players"], areas: ["events", "players"], title: "Make a season, clinic or training", body: "Home → Programs and tap +, then New program (players register).\nWork through the steps: type and name, who it's for, season dates, registration and payments, tryouts and open gyms.\nThe program's gear changes any of it later." },
  { key: "sessions", kind: "howto", topic: "Players & tryouts", who: managers, needs: ["court-players"], areas: ["events"], title: "Add a tryout, open gym or training session", body: "Home → Programs, open the program and tap + by Sessions.\nPick the type, gender, grades, date, time and place, and who runs check-in.\nIts players come from the program's registrations." },
  { key: "check-in", kind: "howto", topic: "Players & tryouts", who: [...managers, ...team], needs: ["court-players"], areas: ["events", "practices"], title: "Check players in", body: "Tap the green ✓ Check-in at the top (it shows when you run one).\nOpen the event and tap each player: ? → ✓ → ✗.\nSearch or tap a count to filter. Everyone helping sees the changes." },
  { key: "scrimmages", kind: "howto", topic: "Players & tryouts", who: managers, needs: ["court-players"], areas: ["teams", "events"], title: "Schedule a scrimmage", body: "Home → Programs, open the season and tap + by Scrimmages.\nPick the teams (or an outside team, or TBD), date, time and gym.\nIt shows on the teams' pages." },
  { key: "registrations-players", kind: "faq", topic: "Players & tryouts", who: ["owner"], needs: ["court-players"], title: "Where do I see everyone who registered?", body: "Home → Registrations: newest, by grade, by team (Not on a team first) or Fees owed. Tap a player for parents, program, birthdate and fees." },
  { key: "families", kind: "faq", topic: "Players & tryouts", who: managers, needs: ["court-players"], areas: ["players", "teams"], title: "How do I find or fix a family's information?", body: "Members → Families shows each family with guardians and fees; Members → Players shows each player. Open a player to add or edit a parent. Undo goes back to the registration." },

  // ---- Members & roles
  { key: "give-role", kind: "howto", topic: "Members & roles", who: admins, title: "Give someone a role", body: "Home → Members → Staff and tap +.\nPick Director, then their areas (Owners can also add Admins and Owners).\nPick the person, or enter a new one's name and cell. They log in with starter PIN 1234." },
  { key: "role-levels", kind: "faq", topic: "Members & roles", who: managers, title: "What can Owners, Admins and Directors do?", body: "Owner: everything, including choosing Admins, payments and deleting the organization. Admin: every area, settings and choosing Directors. Director: only the areas given, like Teams, Players, Practices, Facilities, Programs, Scheduling or Scores." },
  { key: "reset-login", kind: "howto", topic: "Members & roles", who: admins, title: "Reset someone's login", body: "Home → Members, find the person and tap their gear.\nTap Reset login: their PIN goes back to 1234 and they confirm their email again.\nTell them to log in with their cell." },
  { key: "view-as", kind: "faq", topic: "Members & roles", who: admins, title: "Can I see what someone else sees?", body: "Yes. Tap 👁 View as by their name. You see the app as they do, view only; an orange bar shows who. Tap Stop to come back." },
  { key: "remove-owner", kind: "faq", topic: "Members & roles", who: ["owner"], title: "How do I remove an Owner?", body: "Members → Staff → Remove Owner asks them first: they approve it on their own Home, and stay an Admin. An organization always keeps at least one Owner." },
  { key: "join-requests", kind: "howto", topic: "Members & roles", who: admins, title: "Approve someone asking to join", body: "Home → Members flashes red with Requests while someone waits.\nOpen it and see who they are and what they asked for.\nApprove or deny." },

  // ---- Programs & leagues (CourtEvents)
  { key: "new-league", kind: "howto", topic: "Programs & leagues", who: managers, needs: ["court-teams"], areas: ["programs"], title: "Set up a League, Circuit or Tournament", body: "Home → Programs and tap +.\nEnter the type, name, season and registration dates.\nAdd divisions (or copy them from another program), then the Game & Bracket Days.\nIn its gear set fees and options, grades accepted, REC open to, grade requirements, rules and logo." },
  { key: "rec-open-to", kind: "faq", topic: "Programs & leagues", who: managers, needs: ["court-teams"], areas: ["programs"], title: "How do I limit REC to certain organizations?", body: "The program's gear → REC open to: Everyone, or Only these organizations. Only organizations with CourtSync and teams of their own are listed. COMP stays open to all." },
  { key: "org-prices", kind: "howto", topic: "Programs & leagues", who: managers, needs: ["court-teams"], areas: ["programs"], title: "Give some organizations a different price or Pay later", body: "Open the League's Registrations and its gear, then Organization prices.\nTap + to add a price group: name, price per team and Pay later.\nDrag organizations into it. Each move saves." },
  { key: "league-registrations", kind: "faq", topic: "Programs & leagues", who: ["owner"], needs: ["court-teams"], title: "Where are registrations, payments and refunds?", body: "Open the League under Programs, then Registrations: every team, what it registered for and whether it's paid. Open a team to Mark paid (check or cash) or Refund. Refunded Registrations lists payments whose teams are no longer registered." },
  { key: "outside-clubs", kind: "howto", topic: "Programs & leagues", who: managers, needs: ["court-teams"], areas: ["teams"], title: "Add an outside club's teams", body: "Home → Teams and tap +.\nPick the club, or New club with its name and abbreviation.\nAdd the team, or Import many at once.\nOpen a team to register it. Its coach can then add staff and players." },
  { key: "our-conflicts", kind: "faq", topic: "Rosters", who: [...team, ...managers], needs: ["has-teams"], areas: ["teams", "programs"], title: "Why does it say a player is on two rosters?", body: "They look like a player on another team in the League. Allowed (the same organization, different divisions, never REC and COMP, or the League allowed it) is only noted, with why. NOT ALLOWED is a warning: take them off one roster, fix a wrong name or birthdate, or ask the League. Each warning says why it isn't allowed, in plain words. It shows on the team's page, for its organization on Home → To Do and Teams → Warnings, and to the player's family on their player's team card, naming the other organization and team." },
  { key: "parent-two-rosters", kind: "faq", topic: "Your players", who: ["parent"], needs: ["court-players"], title: "It says my player is on two rosters.", body: "Your player looks like a player on another team in the same League, and the League's rules don't allow it. The warning says which rule.\nOften it's a name or birthdate typed differently. The organization and the League sort it out; ask your coach if you have questions." },
  { key: "roster-conflicts", kind: "howto", topic: "Programs & leagues", who: managers, needs: ["court-teams"], areas: ["programs"], title: "Check for players on two teams", body: "Open Home → To Do → Roster conflicts, or the League's card for the maybes too.\nLook at Conflict, Likely and Check.\nMark each Different players, or Allow it and say why (the teams and their organizations see it). It comes back if either one changes.\nAllowed lists players on two rosters within the rules, with why." },
  { key: "season-emails", kind: "howto", topic: "Programs & leagues", who: managers, needs: ["court-teams"], areas: ["teams", "programs"], title: "Send the Season Guide or Hosting Guide", body: "Home → Teams → Standard emails.\nPick the Season Guide (everyone in the League) or Hosting Guide (its hosts).\nCheck the wording and who gets it, then send." },

  // ---- Scheduling
  { key: "make-schedule", kind: "howto", topic: "Scheduling", who: managers, needs: ["court-teams"], areas: ["scheduling"], title: "Make a Game Day's schedule", body: "Programs → the League → Scheduler, and open the Game Day.\nCreate REC matchups and Create COMP matchups (every division, or inside one), or make them by hand (each drag or swap is saved at once and shows on the Grid); set Bindings for teams that need to play near each other.\nOpen the Grid and place games on gyms, courts and times.\nCheck the warnings, then publish." },
  { key: "publish", kind: "faq", topic: "Scheduling", who: managers, needs: ["court-teams"], areas: ["scheduling", "programs"], title: "How do I publish a schedule?", body: "On the Scheduler each Game Day has a REC and a COMP Publish switch. Only published games show publicly and on team pages. A published game can't be moved: unpublish that level first. To Do on Home lists what isn't published." },
  { key: "request-settings", kind: "howto", topic: "Scheduling", who: managers, needs: ["court-teams"], areas: ["scheduling", "programs"], title: "Set up schedule requests", body: "In the League's Game & Bracket Days, choose which days take requests.\nThe gear sets the time blocks, how many a team may check, and when requests close." },
  { key: "removal-requests", kind: "faq", topic: "Scheduling", who: managers, needs: ["court-teams"], areas: ["scheduling"], title: "A team asked to come off the schedule.", body: "The Scheduler card flashes red: open Removal requests. Approving puts TBD in its games and withdraws the team; then find those games a new opponent." },
  { key: "scoresheets", kind: "howto", topic: "Scheduling", who: managers, needs: ["court-teams"], areas: ["scheduling"], title: "Print scoresheets", body: "Scheduler → the Game Day → Grid, and open a gym.\nTap 🖨 Scoresheets: a page per game with rosters and officials.\nPrint, or save as PDF." },

  // ---- Scores
  { key: "enter-scores", kind: "howto", topic: "Scores & standings", who: managers, areas: ["scores"], title: "Enter scores", body: "Home → Scores, and open the Game Day.\nType both scores, or choose a forfeit, and Save.\nTap a saved score to fix it. A game can't end tied.\nYou score games at your gyms; the League scores all of its games." },
  { key: "score-wrong", kind: "faq", topic: "Scores & standings", who: ["public", "parent", "coach", "staff"], title: "A score is wrong.", body: "Tell the gym's Director of Scores or the League; they fix it on Home → Scores and the standings follow. A picture someone already shared doesn't change." },

  // ---- Gyms & hosting
  { key: "add-gym", kind: "howto", topic: "Gyms & hosting", who: managers, needs: ["court-facilities"], areas: ["facilities", "practices"], title: "Add our gyms", body: "Home → Facilities → Gyms and tap + (or Import for several).\nFind the gym by name so its address and map are right.\nName its courts. Its gear changes the location, pin or courts later." },
  { key: "ask-to-host", kind: "howto", topic: "Gyms & hosting", who: managers, needs: ["sync-host"], areas: ["facilities"], title: "Host a League's games (CourtSync)", body: "Home → Facilities → CourtSync → Leagues, and ask to host.\nOnce the League approves, open your gym's availability and tap its Game Days.\nChoose the League, keep or change the hours, and save.\n🗨️ chats with the League's Scheduler." },
  { key: "host-documents", kind: "faq", topic: "Gyms & hosting", who: managers, needs: ["sync-host"], areas: ["facilities", "scores"], title: "Where are the rules and a blank scoresheet?", body: "Home → Facilities → CourtSync → Documents." },
  { key: "host-officials", kind: "faq", topic: "Gyms & hosting", who: managers, needs: ["sync-host"], areas: ["facilities"], title: "Who brings officials to our gym?", body: "Each gym can be set to an officials group in CourtSync. The group's Assigner puts referees on the games there." },
  { key: "approve-hosts", kind: "howto", topic: "Gyms & hosting", who: managers, needs: ["sync-scheduler"], areas: ["facilities", "scheduling"], title: "Approve hosts for our games (CourtSync)", body: "Home → Facilities → CourtSync → Hosting Organizations.\nApprove or decline each request.\nGame days shows each host's courts; Courts limits a court to certain divisions.\n🗨️ chats with a host." },
  { key: "courtsync-what", kind: "faq", topic: "Gyms & hosting", who: managers, needs: ["court-facilities"], areas: ["facilities"], title: "What is CourtSync?", body: "It connects organizations: a League's Scheduler, the hosts whose gyms it plays in, and officials groups. Host: offer your gyms. Scheduler (with CourtEvents): others host your games. Officials: work leagues' games. It's free; CourtCaptain turns it on for now (ask in a chat below)." },
  { key: "directions-wrong", kind: "faq", topic: "Gyms & hosting", who: managers, needs: ["court-facilities"], areas: ["facilities"], title: "Directions go to the wrong place.", body: "Facilities → Gyms → the gym's gear → Location. Set the address, or move the pin to the right door. Directions everywhere use it." },

  // ---- Officials
  { key: "official-answer", kind: "howto", topic: "Officials", who: ["official"], title: "Answer the games I'm assigned", body: "Tap your name to open My dashboard.\nUnder Games to officiate, open the date.\nTap ✓ if you're good for the game, ✗ if you can't make it. Your Assigner sees it.\nEach game shows its gym and Directions." },
  { key: "official-recruit", kind: "faq", topic: "Officials", who: ["official"], title: "I applied. Why have I no games?", body: "New officials start as Recruits, who can't be scheduled. The group's Assigner sets your level; then you can be assigned." },
  { key: "apply-official", kind: "howto", topic: "Officials", who: ["public"], title: "Become an official", body: "On the public page, open Apply to officiate.\nEnter your name, cell and experience.\nThe group's Assigner contacts you and sets your level." },
  { key: "add-officials", kind: "howto", topic: "Officials", who: managers, needs: ["court-officials"], areas: ["officials"], title: "Add officials", body: "Members → Officials and tap + (or Import officials: First, Last, Cell, Email, Level).\nSet each one's level. Recruits can't be scheduled.\nAccept recruits puts Apply to officiate on your public page." },
  { key: "assign-officials", kind: "howto", topic: "Officials", who: managers, needs: ["court-officials"], areas: ["officials"], title: "Assign officials to games", body: "Home → Games to officiate; red means open spots.\nOpen the date and gym, and put an official on each spot.\nA green ✓ means they accepted, red ✗ that they can't." },
  { key: "officiate-league", kind: "howto", topic: "Officials", who: managers, needs: ["sync-officials"], areas: ["officials"], title: "Work a league's games (CourtSync)", body: "Facilities → CourtSync → Leagues to officiate, and ask.\nOnce approved, the gyms set to your group send you their games.\nThey show under Games to officiate." },

  // ---- Chat & alerts
  { key: "use-chat", kind: "howto", topic: "Chat & alerts", who: [...team, ...managers], needs: ["chat"], title: "Use Chat", body: "Tap 💬 at the top.\nSearch, or open Groups, Teams, Coaches or Direct messages.\nThe 🗨️ icons on cards open that chat right there.\nDirectors can open every chat." },
  { key: "read-alerts", kind: "faq", topic: "Chat & alerts", who: ["everyone"], title: "Where are my alerts?", body: "Tap the bell. New ones pop up when you open the app: tap Got it. Alerts from all your organizations are in one list." },
  { key: "send-alert", kind: "howto", topic: "Chat & alerts", who: managers, needs: ["alerts"], title: "Send an alert", body: "Tap the bell at the top, or a bell on a team, grade or group, to reach just them.\nChoose who: everyone, roles, teams or people.\nCheck who it reaches, then send. Sent shows who has read it, and can remove it." },
  { key: "no-phone-notify", kind: "faq", topic: "Chat & alerts", who: ["everyone"], title: "Will my phone notify me?", body: "Not yet. Alerts pop up, and chats show a count, when you open the app." },

  // ---- Settings & payments
  { key: "org-settings", kind: "howto", topic: "Settings & payments", who: admins, title: "Change our name, logo, color or abbreviation", body: "Tap the gear at the top.\nOpen General: abbreviation, Default Alternate name, color and logo (Owners also change the name).\nYour login link is there too." },
  { key: "features", kind: "faq", topic: "Settings & payments", who: admins, title: "Which features do we have?", body: "The gear → Features & Upgrades lists what's on and what can be added. Feature Settings has each feature's options and Director roles. To add a feature, start a chat below." },
  { key: "warnings", kind: "faq", topic: "Settings & payments", who: admins, title: "How do I change which warnings show?", body: "The gear → Warning Configurations, by feature: rosters, birthdates, uniform numbers, unregistered teams and, with CourtPlayers, grade requirements." },
  { key: "connect-stripe", kind: "howto", topic: "Settings & payments", who: ["owner"], title: "Take card payments", body: "The gear → Payments → Connect Stripe.\nFinish Stripe's sign-up for your organization; money goes to its own bank.\nChoose who pays the card fee: you, or added for the team.\nConnected ✓ means teams can pay by card." },
  { key: "delete-org", kind: "faq", topic: "Settings & payments", who: ["owner"], title: "How do I delete our organization?", body: "The gear → Delete organization, once it has no teams. It can't be undone. Thunder and Scenic City can't be deleted here." },

  // ---- Public page & sharing
  { key: "public-page", kind: "faq", topic: "Public page & sharing", who: managers, title: "What does our public page show?", body: "Your banner and season numbers, programs or the League you're in, your teams in a current event, gyms you host in, and pictures to share. No one needs a login, and it never shows contact information. Tap your logo at the top to see it." },
  { key: "share-news", kind: "howto", topic: "Public page & sharing", who: ["public", "coach", ...managers], title: "Share the news on social media", body: "On the public page, swipe through Share the news.\nTap a picture, like Register a new team or the countdown.\nTap Share picture for Instagram, Facebook, X or Messages, or Save picture. They update by themselves." },
  { key: "share-login", kind: "faq", topic: "Public page & sharing", who: managers, title: "What link do I give our coaches and families?", body: "Your login link: tap the share icon by your organization's name at the top. It's also your public page." },
];
